export interface Owned { qty: number; avg: number; ltp: number; }

/** Net shares owned per symbol (holdings + positions), with weighted avg cost. */
export function ownedBySymbol(): Record<string, Owned> {
  const owned: Record<string, Owned> = {};
  const add = (symbol: string, qty: number, price: number, ltp: number) => {
    const o = owned[symbol] ?? (owned[symbol] = { qty: 0, avg: 0, ltp });
    const cost = o.avg * o.qty + price * qty;
    o.qty += qty;
    o.avg = o.qty !== 0 ? cost / o.qty : 0;
    o.ltp = ltp;
  };
  for (const h of SEED_HOLDINGS) add(h.symbol, h.qty, h.avgPrice, h.currentPrice);
  for (const p of SEED_POSITIONS) add(p.symbol, p.qty, p.entryPrice, p.currentPrice);
  return owned;
}
